-- Select consumer planning and writing through declared profiles.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @trigger_name nvarchar(517), @triggers CURSOR;
SET @triggers=CURSOR LOCAL FAST_FORWARD FOR
 SELECT QUOTENAME(s.name)+N'.'+QUOTENAME(t.name)
 FROM sys.triggers t JOIN sys.objects o ON o.object_id=t.parent_id
 JOIN sys.schemas s ON s.schema_id=o.schema_id
 WHERE o.type='U' AND s.name IN ('model','source')
 AND (t.name LIKE 'guard%' OR t.name LIKE '%immutable%');
OPEN @triggers;
FETCH NEXT FROM @triggers INTO @trigger_name;
WHILE @@FETCH_STATUS=0 BEGIN
 EXEC(N'DROP TRIGGER '+@trigger_name);
 FETCH NEXT FROM @triggers INTO @trigger_name;
END;
CLOSE @triggers;
DEALLOCATE @triggers;

DECLARE @object bigint,@definition bigint,@digest binary(32);
EXEC model.put_semantic_definition 'MECHANIC',N'sidefx:mechanics',N'identity',
 N'{"authorityId":"cell-execution-protocol.v1","mechanic":{"mechanicId":"identity","meaning":"Return the admitted input unchanged.","effectClassification":"pure","inputContractId":"semantic-value.v1","outcomeContractId":"semantic-value.v1","sourceProfiles":["semantic-value-provider.v1"],"nativeFloor":false}}',
 @object OUTPUT,@definition OUTPUT,@digest OUTPUT;
DECLARE @mechanic bigint=(SELECT mechanic_pk FROM model.mechanic WHERE semantic_object_pk=@object);
IF @mechanic IS NULL BEGIN
 INSERT model.mechanic(namespace_pk,mechanic_id,semantic_object_pk,object_kind)
 SELECT namespace_pk,N'identity',@object,'MECHANIC' FROM model.semantic_object WHERE semantic_object_pk=@object;
 SET @mechanic=SCOPE_IDENTITY();
END;
IF NOT EXISTS(SELECT 1 FROM model.mechanic_version WHERE semantic_object_definition_pk=@definition)
 INSERT model.mechanic_version(mechanic_pk,semantic_object_pk,semantic_object_definition_pk,definition_digest,name,mechanic_kind,definition_profile,object_kind,_owner_definition_pk,_canonical_pointer)
 VALUES(@mechanic,@object,@definition,@digest,N'Return the admitted input unchanged.','pure','cell-execution-protocol.v1','MECHANIC',@definition,N'');
DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @bindings TABLE(profile_id nvarchar(400) COLLATE Latin1_General_100_BIN2,provider_id nvarchar(400) COLLATE Latin1_General_100_BIN2,role nvarchar(40));
INSERT @bindings VALUES
 (N'node-deterministic-semantic-value-provider.v1',N'ScenarioKernel.NodePlatform.Execution.AuthorityTransformation',N'semantic-value'),
 (N'python-deterministic-semantic-value-provider.v1',N'scenario_kernel.adapters.SemanticTransformationEngine',N'semantic-value'),
 (N'csharp-deterministic-semantic-value-provider.v1',N'ScenarioKernel.Adapters.Consumer.SemanticTransformationEngine',N'semantic-value'),
 (N'node-deterministic-semantic-value-provider.v1',N'ScenarioKernel.NodePlatform',N'identity'),
 (N'python-deterministic-semantic-value-provider.v1',N'scenario_kernel.platform.consumer',N'identity'),
 (N'csharp-deterministic-semantic-value-provider.v1',N'ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform',N'identity');
SELECT * INTO #selected FROM analysis.v_selected_semantic_definition WHERE estate_model_pk=@estate AND object_kind IN('MECHANIC','PROVIDER');
INSERT model.provider_mechanic_implementation(provider_definition_pk,mechanic_version_pk,provider_profile_version_pk,role,_owner_definition_pk,_canonical_pointer)
SELECT pd.provider_definition_pk,mv.mechanic_version_pk,p.provider_profile_version_pk,b.role,pd.semantic_object_definition_pk,N''
FROM @bindings b JOIN analysis.v_target_provider_profile p ON p.estate_model_pk=@estate AND p.provider_profile_id=b.profile_id
JOIN model.provider provider ON provider.provider_id=b.provider_id
JOIN model.provider_definition pd ON pd.provider_pk=provider.provider_pk
JOIN #selected d ON d.semantic_object_definition_pk=pd.semantic_object_definition_pk
JOIN #selected md ON md.object_kind='MECHANIC' AND JSON_VALUE(md.definition_json,'$.semantics.mechanic.effectClassification')='pure'
JOIN model.mechanic_version mv ON mv.semantic_object_definition_pk=md.semantic_object_definition_pk
WHERE ((b.role='identity' AND md.declared_id='identity') OR (b.role='semantic-value' AND md.declared_id<>'identity'))
 AND NOT EXISTS(SELECT 1 FROM model.provider_mechanic_implementation i WHERE i.provider_definition_pk=pd.provider_definition_pk
 AND i.mechanic_version_pk=mv.mechanic_version_pk AND i.provider_profile_version_pk=p.provider_profile_version_pk);
SELECT 'pure_mechanic_bindings' AS result_set,@@ROWCOUNT AS added;
GO

DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1),@port bigint,@previous bigint;
SELECT @port=pv.port_pk,@previous=pv.port_version_pk FROM analysis.v_selected_semantic_definition d
JOIN model.port_version pv ON pv.semantic_object_definition_pk=d.semantic_object_definition_pk
WHERE d.estate_model_pk=@estate AND d.object_kind='PORT' AND d.namespace_id=N'sidefx:capability:plan-capability-embodiment' AND d.declared_id=N'plan-capability-embodiment-port';
DECLARE @object bigint,@definition bigint,@digest binary(32);
